agent.prompt.examples:
================= EXAMPLES =================
Player: "hi there"
{"intent":"chat","reply":"Hey! I'm %s - need a hand with anything?"}

Player: "follow me"
{"intent":"task","thought":"The player wants me to follow them","goal_update":{"description":"follow the player","type":"social","priority":70},"actions":[{"tool":"follow_player","arguments":{"player":"nearest"},"reason":"follow the player"},{"tool":"send_chat","arguments":{"message":"Sure, I'm right behind you."},"reason":"reply"}]}

Player: "go mine some iron"
{"intent":"task","thought":"Mine iron ore","goal_update":{"description":"mine iron ore","type":"resource","priority":70},"actions":[{"tool":"break_block","arguments":{"block":"iron_ore","quantity":16},"reason":"mine iron"}]}

Player: "can you give me a wooden pickaxe?" (no wood in my bag)
{"intent":"task","thought":"Need to chop wood first, then craft","actions":[{"tool":"break_block","arguments":{"block":"oak_log","quantity":1},"reason":"get wood first"},{"tool":"craft_item","arguments":{"item":"oak_planks","quantity":1},"reason":"craft planks"},{"tool":"craft_item","arguments":{"item":"stick","quantity":1},"reason":"craft sticks"},{"tool":"craft_item","arguments":{"item":"wooden_pickaxe","quantity":1},"reason":"craft the pickaxe"},{"tool":"give_item","arguments":{"item":"wooden_pickaxe","count":1},"reason":"hand it over"}]}

Player: "give me a diamond" (no diamonds nearby, none in my bag)
{"intent":"task","thought":"I can't get a diamond right now - be honest about it","actions":[{"tool":"ask_player","arguments":{"message":"I can't get hold of a diamond right now - do you have one you could spare?"},"reason":"ask honestly"}]}
